<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.*" />
  </ItemGroup>
</Project>
EOF
cat > Program.cs << 'CEOF'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Collect all errors
var errors = new List<(string project, string code, string message, string file, int line)>();
build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = (BaseNode)e;
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project p) { proj = p.Name; break; }
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? e.ToString(), e.File ?? "", e.LineNumber));
});

Console.WriteLine($"Total errors: {errors.Count}\n");

// Group by project
var byProject = errors.GroupBy(e => e.project).OrderBy(g => g.Key);
foreach (var g in byProject) {
    Console.WriteLine($"=== Project: {g.Key} ===");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
    Console.WriteLine();
}

// Also check for failed targets / dependency failures
Console.WriteLine("=== Project build results ===");
build.VisitAllChildren<Project>(p => {
    if (p.Succeeded == false) {
        Console.WriteLine($"  FAILED: {p.Name} (target: {p.TargetFramework})");
    }
});
CEOF
