using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// List all projects and their references
Console.WriteLine("=== All projects in build ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name} (TFM: {p.TargetFramework}) - Children: {p.Children.Count}");
});

// Check for package references in Services.csproj
Console.WriteLine("\n=== Package/Project references for failed project ===");
build.VisitAllChildren<Project>(p => {
    if (p.Name == "Services.csproj") {
        p.VisitAllChildren<NamedNode>(n => {
            var name = n.Name?.ToLower() ?? "";
            if (name.Contains("packagereference") || name.Contains("nuget") || name.Contains("restore") || name.Contains("newtonsoft"))
                Console.WriteLine($"  {n.GetType().Name}: {n.Name} = {n}");
        });
        // Also look at items
        p.VisitAllChildren<Item>(i => {
            if (i.Name?.Contains("PackageReference") == true || i.Text?.Contains("Newtonsoft") == true)
                Console.WriteLine($"  Item: {i.Name} = {i.Text}");
        });
        p.VisitAllChildren<Folder>(f => {
            if (f.Name?.Contains("PackageReference") == true || f.Name?.Contains("Restore") == true)
                Console.WriteLine($"  Folder: {f.Name}");
        });
    }
});

// Check MSB errors related to restore
Console.WriteLine("\n=== NuGet/Restore messages ===");
build.VisitAllChildren<Message>(m => {
    var text = m.Text ?? "";
    if (text.Contains("Newtonsoft") || text.Contains("restore") && text.Contains("Services"))
        Console.WriteLine($"  {text.Substring(0, Math.Min(text.Length, 200))}");
});

// Failed projects cascade check
Console.WriteLine("\n=== Failed project evaluation ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name}: HasErrors={p.HasErrors}");
});
CEOF
