using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Get package reference details with metadata
Console.WriteLine("=== Package references with metadata ===");
build.VisitAllChildren<AddItem>(ai => {
    if (ai.Name == "PackageReference") {
        var proj = "";
        var node = (BaseNode)ai;
        while (node.Parent != null) {
            node = (BaseNode)node.Parent;
            if (node is Project p) { proj = p.Name; break; }
        }
        foreach (var child in ai.Children) {
            Console.WriteLine($"  [{proj}] {child}");
            if (child is Item item) {
                foreach (var meta in item.Children.OfType<Metadata>()) {
                    Console.WriteLine($"    {meta.Name} = {meta.Value}");
                }
            }
        }
    }
});

// Check NuGet restore output
Console.WriteLine("\n=== NuGet restore results ===");
build.VisitAllChildren<Message>(m => {
    var t = m.Text ?? "";
    if (t.Contains("Newtonsoft") || (t.Contains("NU") && t.Contains("Services")))
        Console.WriteLine($"  {t.Substring(0, Math.Min(200, t.Length))}");
});

// Check if Api depends on Services
Console.WriteLine("\n=== Project references (AddItem) ===");
build.VisitAllChildren<AddItem>(ai => {
    if (ai.Name == "ProjectReference") {
        var proj = "";
        var node = (BaseNode)ai;
        while (node.Parent != null) {
            node = (BaseNode)node.Parent;
            if (node is Project p) { proj = p.Name; break; }
        }
        foreach (var child in ai.Children)
            Console.WriteLine($"  [{proj}] -> {child}");
    }
});

// Check for MSB4181 or dependency build failed
Console.WriteLine("\n=== Dependency/cascade errors ===");
build.VisitAllChildren<Error>(e => {
    if (e.Code?.StartsWith("MSB") == true)
        Console.WriteLine($"  {e.Code}: {e.Text}");
});
build.VisitAllChildren<Warning>(w => {
    if (w.Code == "MSB3245" || w.Code == "MSB4181" || w.Code?.StartsWith("MSB") == true)
        Console.WriteLine($"  Warning {w.Code}: {w.Text?.Substring(0, Math.Min(200, w.Text?.Length ?? 0))}");
});
