    if (i.Name?.Contains("Services") == true || i.ProjectFilePath?.Contains("Services") == true)
        Console.WriteLine($"  Import: {i.Name} -> {i.ProjectFilePath}");
});

// Look at evaluation for package references
Console.WriteLine("\n=== Evaluation items ===");
build.VisitAllChildren<ProjectEvaluation>(pe => {
    Console.WriteLine($"  ProjectEvaluation: {pe.Name}");
    pe.VisitAllChildren<AddItem>(ai => {
        if (ai.Name == "PackageReference") {
            Console.Write($"    [{pe.Name}] PackageReference: ");
            foreach (var c in ai.Children) Console.Write($"{c} ");
            Console.WriteLine();
        }
    });
});
