        if (ai.Name == "PackageReference") {
            foreach (var c in ai.Children) {
                if (c is Item item) {
                    var metas = string.Join(", ", item.Children.OfType<Metadata>().Select(m => $"{m.Name}={m.Value}"));
                    Console.WriteLine($"  [{pe.Name}] {item.Text} ({metas})");
                }
            }
        }
    });
});

// Get embedded file contents from binlog
Console.WriteLine("\n=== Embedded source files ===");
var files = build.SourceFiles;
if (files != null) {
    foreach (var kv in files) {
        if (kv.Key.Contains("Services") || kv.Key.Contains("csproj") || kv.Key.Contains("UserService")) {
            Console.WriteLine($"\n--- {kv.Key} ---");
            Console.WriteLine(kv.Value);
        }
    }
}
